import { Flashcard } from "../types";

export const STARTER_DECK: Flashcard[] = [
  { id: "dd-1", category: "Foundations", front: "What is epidemiology?", back: "The study of the distribution and determinants of health conditions in specified populations, and the application of that study to control health problems.", source: "Disease Detectives wiki" },
  { id: "dd-2", category: "Foundations", front: "What are the person, place, and time triad used for?", back: "Descriptive epidemiology: describe who is affected, where cases occur, and when they occur.", source: "Disease Detectives wiki" },
  { id: "dd-3", category: "Foundations", front: "What are agent, host, and environment?", back: "The chain-of-transmission triad: an external agent, a susceptible host, and the environment where they meet.", source: "Disease Detectives wiki" },
  { id: "dd-4", category: "Foundations", front: "Define incidence.", back: "The rate of new cases in a population during a specified period.", source: "Disease Detectives wiki" },
  { id: "dd-5", category: "Foundations", front: "Define prevalence.", back: "The number of existing cases in a population; point prevalence is measured at one time and period prevalence over an interval.", source: "Disease Detectives wiki" },
  { id: "dd-6", category: "Foundations", front: "What is an index case?", back: "The first identified case of a disease in a specific setting, sometimes called patient zero.", source: "Disease Detectives wiki" },
  { id: "dd-7", category: "Outbreaks", front: "What are the four parts of a case definition?", back: "Clinical information, characteristics of affected people, place, and time sequence.", source: "Outbreak investigation" },
  { id: "dd-8", category: "Outbreaks", front: "Confirmed vs. probable vs. possible case?", back: "Confirmed: lab confirmation plus signs/symptoms. Probable: signs/symptoms without lab confirmation. Possible: some signs/symptoms but unclear evidence.", source: "Outbreak investigation" },
  { id: "dd-9", category: "Outbreaks", front: "What is a line listing?", back: "A chart of cases containing identifying, demographic, clinical, time, place, and risk-factor information.", source: "Outbreak investigation" },
  { id: "dd-10", category: "Outbreaks", front: "What is a point-source epidemic curve?", back: "A rapid rise to one clear peak followed by a gradual decline after a shared exposure over a short period.", source: "Disease Detectives wiki" },
  { id: "dd-11", category: "Outbreaks", front: "What is a propagated epidemic curve?", back: "A series of successively spaced peaks caused by person-to-person spread; peak spacing can suggest the incubation period.", source: "Disease Detectives wiki" },
  { id: "dd-12", category: "Outbreaks", front: "What should happen after a hypothesis is evaluated epidemiologically?", back: "Reconsider, refine, and re-evaluate it, then compare it with laboratory or environmental evidence.", source: "13 outbreak-investigation steps" },
  { id: "dd-13", category: "Study Design", front: "Case-control vs. cohort study?", back: "Case-control starts with disease status and looks back for exposures. Cohort starts with exposure status and compares later outcomes.", source: "Question Marathon" },
  { id: "dd-14", category: "Study Design", front: "What is a cross-sectional study?", back: "A snapshot in time, often using a survey or health questionnaire; exposure and outcome are measured together.", source: "Disease Detectives wiki" },
  { id: "dd-15", category: "Study Design", front: "Which study is useful for rare exposures?", back: "A cohort study is good for rare exposures and allows direct risk calculations.", source: "Disease Detectives wiki" },
  { id: "dd-16", category: "Study Design", front: "Which study is useful for rare diseases?", back: "A case-control study is efficient for rare diseases and long latency periods.", source: "Disease Detectives wiki" },
  { id: "dd-17", category: "Study Design", front: "What is the ecological fallacy?", back: "Assuming relationships observed between groups necessarily apply to individuals within those groups.", source: "Study design review" },
  { id: "dd-18", category: "Statistics", front: "Attack rate formula", back: "Number of people who become ill divided by the total number of people in the group.", source: "Disease Detectives wiki" },
  { id: "dd-19", category: "Statistics", front: "Relative risk formula", back: "Incidence in the exposed group divided by incidence in the unexposed group: [a/(a+b)] / [c/(c+d)].", source: "Disease Detectives wiki" },
  { id: "dd-20", category: "Statistics", front: "Odds ratio formula", back: "For a 2×2 table, odds ratio = (a×d)/(b×c). It is commonly used in case-control studies.", source: "Disease Detectives wiki" },
  { id: "dd-21", category: "Statistics", front: "What does a p-value below 0.05 usually mean?", back: "Under the chosen alpha threshold, the result is statistically significant; reject the null hypothesis, while remembering that bias and confounding may remain.", source: "Disease Detectives wiki" },
  { id: "dd-22", category: "Statistics", front: "Type I vs. Type II error", back: "Type I rejects a true null hypothesis (false positive). Type II fails to reject a false null hypothesis (false negative).", source: "Disease Detectives wiki" },
  { id: "dd-23", category: "Statistics", front: "Sensitivity vs. specificity", back: "Sensitivity = true positives / all with disease. Specificity = true negatives / all without disease.", source: "Disease Detectives wiki" },
  { id: "dd-24", category: "Statistics", front: "Correlation vs. causation", back: "Correlation shows a relationship, not that one variable causes the other. Confounding variables and bias can create apparent associations.", source: "Question Marathon" },
  { id: "dd-25", category: "Surveillance", front: "Five steps of surveillance", back: "Data collection, data analysis, data interpretation, data dissemination, and link to action.", source: "Disease Detectives wiki" },
  { id: "dd-26", category: "Surveillance", front: "Passive vs. active surveillance", back: "Passive relies on routine reports from providers. Active health agencies contact providers to seek reports and usually get more complete data.", source: "Disease Detectives wiki" },
  { id: "dd-27", category: "Surveillance", front: "What is syndromic surveillance?", back: "Monitoring signs or proxies, such as school absences or medication sales, when quick detection matters or diagnosis is difficult.", source: "Disease Detectives wiki" },
  { id: "dd-28", category: "Surveillance", front: "What is sentinel surveillance?", back: "Selected professionals or sites report events to represent a geographic area or group and monitor trends.", source: "Disease Detectives wiki" },
  { id: "dd-29", category: "Transmission", front: "Six links in the chain of infection", back: "Agent → reservoir → portal of exit → mode of transmission → portal of entry → susceptible host.", source: "Disease Detectives wiki" },
  { id: "dd-30", category: "Transmission", front: "Mechanical vs. biological vector", back: "A mechanical vector carries an agent without a life-stage change; a biological vector allows the agent to multiply or change inside it.", source: "Disease Detectives wiki" },
  { id: "dd-31", category: "Transmission", front: "What is herd immunity?", back: "Protection of a community when a critical proportion is immune, breaking transmission and protecting some non-immune people.", source: "Disease Detectives wiki" },
  { id: "dd-32", category: "Transmission", front: "Herd-immunity threshold formula", back: "For a 100%-effective vaccine, threshold = 1 − (1/R₀). With vaccine efficacy E, use (1 − 1/R₀) / E.", source: "Disease Detectives wiki" },
  { id: "dd-33", category: "Prevention", front: "Primordial, primary, secondary, tertiary prevention", back: "Primordial prevents risk factors; primary prevents initial exposure; secondary screens/treats latent disease; tertiary limits symptomatic disease and disability.", source: "Disease Detectives wiki" },
  { id: "dd-34", category: "Prevention", front: "What is FAT TOM?", back: "Food, acidity, time, temperature, oxygen, and moisture—the six conditions that favor foodborne pathogen growth.", source: "Foodborne illness review" },
  { id: "dd-35", category: "Causation", front: "What does temporality mean in Hill’s criteria?", back: "The exposure or suspected cause must occur before the outcome.", source: "Hill’s criteria review" },
  { id: "dd-36", category: "Causation", front: "What are Koch’s postulates used for?", back: "Criteria for linking a specific microorganism causally to a disease: find it in cases, isolate/culture it, reproduce disease, and re-isolate it.", source: "Disease Detectives wiki" },
  { id: "dd-37", category: "Foundations", front: "Incubation period vs. latent period", back: "Incubation is exposure to first symptoms. Latent period is exposure to becoming infected/detectable.", source: "Disease Detectives wiki" },
  { id: "dd-38", category: "Foundations", front: "Pathogenicity vs. virulence vs. infectivity", back: "Pathogenicity is the ability to cause disease; virulence is the severity caused; infectivity is the ability to establish infection after exposure.", source: "Question Marathon" },
  { id: "dd-39", category: "Foundations", front: "Morbidity vs. mortality", back: "Morbidity describes illness in a population; mortality describes death in a population.", source: "Disease Detectives wiki" },
  { id: "dd-40", category: "Foundations", front: "What is case fatality rate?", back: "Deaths caused by a disease divided by the number of people with that disease.", source: "Disease Detectives wiki" },
  { id: "dd-41", category: "Outbreaks", front: "What is an outbreak?", back: "An occurrence of cases in a particular place and time that is greater than expected or otherwise unusual.", source: "Question Marathon" },
  { id: "dd-42", category: "Outbreaks", front: "Cluster vs. epidemic vs. pandemic", back: "A cluster is an aggregation of cases in place/time; an epidemic exceeds expected cases in a population; a pandemic is an epidemic spanning countries or continents.", source: "Question Marathon" },
  { id: "dd-43", category: "Outbreaks", front: "What is a continuous common-source epidemic?", back: "Exposure continues over an extended period, often producing a longer curve; the decline may be sharp when the source is removed.", source: "Disease Detectives wiki" },
  { id: "dd-44", category: "Outbreaks", front: "Why verify the diagnosis?", back: "To ensure the increase is real, confirm testing methods, and rule out laboratory or reporting error before investigating the outbreak.", source: "13 outbreak-investigation steps" },
  { id: "dd-45", category: "Outbreaks", front: "When should control measures begin?", back: "As soon as possible once the source or effective intervention is known; do not wait for every investigation step to finish.", source: "13 outbreak-investigation steps" },
  { id: "dd-46", category: "Study Design", front: "Advantages of a randomized controlled trial", back: "Random assignment can reduce confounding and provides strong evidence for an intervention, but trials can be expensive, time-consuming, or unethical.", source: "Disease Detectives wiki" },
  { id: "dd-47", category: "Study Design", front: "What is a retrospective cohort study?", back: "A cohort study that uses past records to classify exposure and then compares outcomes that occurred afterward.", source: "Question Marathon" },
  { id: "dd-48", category: "Study Design", front: "What is confounding?", back: "A third variable related to both exposure and outcome that distorts their apparent relationship.", source: "Disease Detectives wiki" },
  { id: "dd-49", category: "Bias", front: "What is selection bias?", back: "Systematic error caused by how participants are selected, retained, or lost from a study.", source: "Disease Detectives wiki" },
  { id: "dd-50", category: "Bias", front: "What is recall bias?", back: "Systematic difference in how accurately people remember or report past exposures, often a concern in case-control studies.", source: "Disease Detectives wiki" },
  { id: "dd-51", category: "Bias", front: "Internal vs. external validity", back: "Internal validity asks whether the study result is due to the intervention rather than bias/confounding. External validity asks whether it generalizes elsewhere.", source: "Disease Detectives wiki" },
  { id: "dd-52", category: "Statistics", front: "Mean, median, and mode", back: "Mean is the average; median is the middle value; mode is the most frequent value. Median is less affected by outliers.", source: "Disease Detectives wiki" },
  { id: "dd-53", category: "Statistics", front: "What does standard deviation describe?", back: "The spread of observations around the mean, in the same units as the original data.", source: "Disease Detectives wiki" },
  { id: "dd-54", category: "Statistics", front: "What is a confidence interval?", back: "A range calculated from sample data that estimates a population parameter at a stated confidence level; it does not automatically remove bias or confounding.", source: "Disease Detectives wiki" },
  { id: "dd-55", category: "Statistics", front: "What is a chi-square test used for?", back: "Testing whether observed categorical counts differ from expected counts or whether two categorical variables are associated.", source: "Disease Detectives wiki" },
  { id: "dd-56", category: "Statistics", front: "When is Fisher’s exact test useful?", back: "For testing a 2×2 categorical association, especially when sample or expected cell counts are small.", source: "Disease Detectives wiki" },
  { id: "dd-57", category: "Statistics", front: "What is a z-score?", back: "The number of standard deviations an observation is from the mean: z = (x − mean) / standard deviation.", source: "Disease Detectives wiki" },
  { id: "dd-58", category: "Surveillance", front: "What is the purpose of surveillance?", back: "To learn disease patterns for prevention and control, guide public-health decisions, and evaluate control measures.", source: "Disease Detectives wiki" },
  { id: "dd-59", category: "Surveillance", front: "What is the fastest reason to use syndromic surveillance?", back: "It can detect a possible outbreak early by tracking symptoms or proxies before laboratory confirmation is available.", source: "Question Marathon" },
  { id: "dd-60", category: "Surveillance", front: "What is PulseNet?", back: "A network and database system that uses bacterial DNA fingerprints, now primarily whole-genome sequencing, to detect clusters and foodborne outbreaks.", source: "Disease Detectives wiki" },
  { id: "dd-61", category: "Surveillance", front: "What is PFGE?", back: "Pulsed-field gel electrophoresis, an older DNA fingerprinting method that separates large DNA fragments using alternating electric-field directions.", source: "Disease Detectives wiki" },
  { id: "dd-62", category: "Transmission", front: "What is a reservoir?", back: "The place where an infectious agent normally lives, grows, and reproduces.", source: "Disease Detectives wiki" },
  { id: "dd-63", category: "Transmission", front: "Contact, vehicle, and vector transmission", back: "Contact transfers directly, indirectly, or by droplets; vehicles carry agents in food, water, air, or objects; vectors are living carriers such as mosquitoes and ticks.", source: "Disease Detectives wiki" },
  { id: "dd-64", category: "Transmission", front: "Quarantine vs. isolation", back: "Quarantine separates people who may have been exposed. Isolation separates people who are infected or ill.", source: "Disease Detectives wiki" },
  { id: "dd-65", category: "Immunity", front: "Active vs. passive immunity", back: "Active immunity comes from making antibodies after infection or vaccination. Passive immunity comes from receiving antibodies and is generally shorter-lived.", source: "Disease Detectives wiki" },
  { id: "dd-66", category: "Immunity", front: "Innate immunity", back: "The body’s natural, nonspecific defenses present from birth, such as skin and stomach acid.", source: "Disease Detectives wiki" },
  { id: "dd-67", category: "Prevention", front: "How can you interrupt a chain of infection?", back: "Target any link: eliminate the agent, control the reservoir, block exit or entry, change transmission, or protect the susceptible host.", source: "Disease Detectives wiki" },
  { id: "dd-68", category: "Prevention", front: "Food-safety controls for foodborne illness", back: "Cook thoroughly, prevent cross-contamination, refrigerate promptly, wash produce, and report suspected foodborne illness.", source: "Disease Detectives wiki" },
  { id: "dd-69", category: "Causation", front: "Name three Hill criteria for causation", back: "Any three: strength, consistency, specificity, alternative explanations, temporality, dose-response, biological plausibility, experimental evidence, and coherence.", source: "Disease Detectives wiki" },
  { id: "dd-70", category: "Causation", front: "What is a dose-response relationship?", back: "As the amount or intensity of exposure increases, the risk or severity of the outcome increases in a consistent pattern.", source: "Hill’s criteria review" },
  { id: "dd-71", category: "Statistics", front: "What is a ratio?", back: "A comparison of two quantities by division; the numerator and denominator do not have to be from the same population.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-72", category: "Statistics", front: "What is a proportion?", back: "A ratio in which the numerator is included in the denominator. It is often expressed as a fraction, decimal, or percentage.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-73", category: "Statistics", front: "What is a rate?", back: "A proportion or ratio that includes a measure of time in the denominator or describes how quickly an event occurs.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-74", category: "Statistics", front: "Why multiply a rate by 1,000 or 100,000?", back: "To express a small risk or rate in a readable standard unit, such as cases per 100,000 population.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-75", category: "Statistics", front: "What is a crude rate?", back: "A rate for an entire population without adjustment for characteristics such as age or sex.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-76", category: "Statistics", front: "What is a specific rate?", back: "A rate calculated for a particular subgroup, such as an age-specific or cause-specific rate.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-77", category: "Statistics", front: "What is a standardized or adjusted rate?", back: "A rate statistically adjusted to allow fair comparison between populations with different distributions of a confounding characteristic.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-78", category: "Statistics", front: "What is an attack rate?", back: "The proportion of an at-risk population that becomes ill during a specified outbreak: new cases / population at risk.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-79", category: "Statistics", front: "What is a secondary attack rate?", back: "The proportion of susceptible contacts who become cases after exposure to a primary case, often used for household or close-contact spread.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-80", category: "Statistics", front: "What is an incidence rate?", back: "New cases divided by the total person-time at risk. It accounts for different amounts of follow-up among participants.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-81", category: "Statistics", front: "What is person-time at risk?", back: "The sum of the time each individual remains susceptible and under observation for becoming a case.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-82", category: "Statistics", front: "What is point prevalence?", back: "Existing cases at one specific point in time divided by the population at that time.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-83", category: "Statistics", front: "What is period prevalence?", back: "All existing cases during a specified time interval divided by the appropriate population.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-84", category: "Statistics", front: "How are incidence and prevalence related?", back: "Prevalence is influenced by incidence and by how long disease lasts. High incidence or longer duration generally increases prevalence.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-85", category: "Statistics", front: "What is risk?", back: "The probability that an individual in a defined population will develop an outcome during a specified period.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-86", category: "Statistics", front: "How do you interpret relative risk (RR) = 1?", back: "The observed risk is the same in exposed and unexposed groups; there is no association on the multiplicative scale.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-87", category: "Statistics", front: "How do you interpret RR > 1 or RR < 1?", back: "RR > 1 suggests increased risk with exposure; RR < 1 suggests a protective association. Consider confidence intervals and bias before concluding causation.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-88", category: "Statistics", front: "What is attributable risk (risk difference)?", back: "Risk in the exposed group minus risk in the unexposed group. It estimates excess risk associated with exposure.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-89", category: "Statistics", front: "What is attributable fraction among the exposed?", back: "The fraction of disease among exposed people attributable to the exposure: (risk exposed − risk unexposed) / risk exposed.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-90", category: "Statistics", front: "What is population attributable risk?", back: "Risk in the total population minus risk in the unexposed group; it estimates the excess population burden associated with exposure.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-91", category: "Statistics", front: "What is the odds of an event?", back: "The probability the event occurs divided by the probability it does not occur: p / (1 − p).", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-92", category: "Statistics", front: "When does an odds ratio approximate relative risk?", back: "When the outcome is rare in both exposed and unexposed groups, commonly when incidence is below about 10%.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-93", category: "Statistics", front: "What is a 2×2 table used for?", back: "Organizing exposure and disease status into exposed/unexposed rows and diseased/not diseased columns to calculate risk measures.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-94", category: "Statistics", front: "How do you calculate expected frequency in a contingency table?", back: "Expected cell count = (row total × column total) / grand total.", source: "Disease Detectives wiki" },
  { id: "dd-95", category: "Statistics", front: "Chi-square degrees of freedom for a 2×2 table", back: "df = (number of rows − 1)(number of columns − 1) = 1 for a 2×2 table.", source: "Disease Detectives wiki" },
  { id: "dd-96", category: "Statistics", front: "What does a chi-square p-value test?", back: "Whether the observed difference or association could plausibly be explained by random variation under the null hypothesis.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-97", category: "Statistics", front: "What is a one-tailed vs. two-tailed test?", back: "A one-tailed test looks for an effect in a specified direction; a two-tailed test looks for an effect in either direction.", source: "Statistics review" },
  { id: "dd-98", category: "Statistics", front: "What is statistical power?", back: "The probability of detecting an effect when it truly exists; power = 1 − beta, where beta is the Type II error probability.", source: "Disease Detectives wiki" },
  { id: "dd-99", category: "Statistics", front: "What increases statistical power?", back: "A larger sample, a larger true effect, less variability, and a higher chosen significance level generally increase power.", source: "Statistics review" },
  { id: "dd-100", category: "Statistics", front: "What is the central limit theorem used for?", back: "With sufficiently large samples, the distribution of sample means tends toward normality even when the original population is not normal.", source: "Statistics review" },
  { id: "dd-101", category: "Statistics", front: "What is a standard error?", back: "A measure of how much a sample statistic, such as a mean, varies from sample to sample; for a mean, SE is approximately s / √n.", source: "Disease Detectives wiki" },
  { id: "dd-102", category: "Statistics", front: "What does a 95% confidence interval mean?", back: "If the same sampling method were repeated many times, about 95% of calculated intervals would contain the true parameter; it is not a 95% probability statement about one fixed interval.", source: "Disease Detectives wiki" },
  { id: "dd-103", category: "Statistics", front: "What is a null hypothesis?", back: "The default claim, usually that there is no association or no difference between groups.", source: "Disease Detectives wiki" },
  { id: "dd-104", category: "Statistics", front: "What does ‘fail to reject’ the null mean?", back: "The evidence is insufficient at the chosen alpha level; it does not prove that the null hypothesis is true.", source: "Disease Detectives wiki" },
  { id: "dd-105", category: "Statistics", front: "What is a t-test used for?", back: "Comparing means when population variance is unknown, including comparing one sample to a value or two independent groups.", source: "Disease Detectives wiki" },
  { id: "dd-106", category: "Statistics", front: "What is a paired t-test?", back: "A test comparing two measurements from the same subjects or matched subjects, such as before-and-after values.", source: "Disease Detectives wiki" },
  { id: "dd-107", category: "Statistics", front: "What is ANOVA used for?", back: "Testing whether the means of three or more groups differ; a significant result says at least one mean differs, not which one.", source: "Disease Detectives wiki" },
  { id: "dd-108", category: "Statistics", front: "What is the Mantel-Haenszel method used for?", back: "Estimating an association while controlling for a stratifying confounder by combining stratum-specific results.", source: "Disease Detectives wiki" },
  { id: "dd-109", category: "Statistics", front: "What is McNemar’s test used for?", back: "Testing paired or matched binary data, such as the same people classified before and after an intervention.", source: "Disease Detectives wiki" },
  { id: "dd-110", category: "Statistics", front: "What is a false positive?", back: "A test result that is positive even though the person does not have the disease.", source: "Disease Detectives wiki" },
  { id: "dd-111", category: "Statistics", front: "What is a false negative?", back: "A test result that is negative even though the person does have the disease.", source: "Disease Detectives wiki" },
  { id: "dd-112", category: "Statistics", front: "Positive predictive value (PPV)", back: "The probability a person truly has disease given a positive test: true positives / all positive tests.", source: "Diagnostic testing review" },
  { id: "dd-113", category: "Statistics", front: "Negative predictive value (NPV)", back: "The probability a person truly does not have disease given a negative test: true negatives / all negative tests.", source: "Diagnostic testing review" },
  { id: "dd-114", category: "Statistics", front: "How does prevalence affect predictive value?", back: "At higher disease prevalence, PPV generally increases and NPV generally decreases; predictive values depend on the population being tested.", source: "Diagnostic testing review" },
  { id: "dd-115", category: "Statistics", front: "What is a histogram?", back: "A graph of the distribution of a continuous numerical variable using adjacent intervals or bins.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-116", category: "Statistics", front: "What is a box-and-whisker plot?", back: "A display of median, quartiles, spread, and potential outliers; it is useful for comparing distributions across groups.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-117", category: "Statistics", front: "What is a scatter plot?", back: "A graph of paired numerical observations used to examine the direction, form, and strength of a possible relationship.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-118", category: "Statistics", front: "What is a bar chart?", back: "A graph using separated bars to compare counts or percentages across categories.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-119", category: "Statistics", front: "What is a line graph useful for?", back: "Showing change or trends over an ordered variable, especially time.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-120", category: "Statistics", front: "What is a spot map?", back: "A map marking the locations of cases or events to reveal geographic clustering or patterns.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-121", category: "Statistics", front: "What makes an epi curve different from a regular histogram?", back: "An epi curve displays cases by time of illness onset or diagnosis and helps infer the outbreak’s source and transmission pattern.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-122", category: "Statistics", front: "What is a logarithmic scale useful for?", back: "Displaying values spanning several orders of magnitude and making relative changes easier to compare.", source: "Data display review" },
  { id: "dd-123", category: "Statistics", front: "Why can a misleading y-axis distort a graph?", back: "Changing the baseline or scale can exaggerate or hide differences; axes, units, intervals, and denominators must be inspected.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-124", category: "Statistics", front: "What is Simpson’s paradox?", back: "An association seen in several groups can reverse or disappear when the groups are combined, often because of confounding or unequal group sizes.", source: "Statistics review" },
  { id: "dd-125", category: "Statistics", front: "What is ecological correlation?", back: "A correlation calculated from group-level data; it cannot safely be assumed to describe relationships between individuals.", source: "Study design review" },
  { id: "dd-126", category: "Statistics", front: "What is the denominator for cumulative incidence?", back: "The population at risk at the beginning of the observation period; do not include people who already have the outcome.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-127", category: "Statistics", front: "What is the denominator for prevalence?", back: "The total population in which existing cases are measured, including people with and without the disease.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-128", category: "Statistics", front: "Can a person contribute more than once to incidence?", back: "For cumulative incidence of a first event, each person contributes once. Incidence rates can count recurrent events when the method allows it.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-129", category: "Statistics", front: "What is a mortality rate?", back: "Deaths in a population during a specified period divided by the population at risk, often reported per 1,000 or 100,000.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-130", category: "Statistics", front: "What is a cause-specific mortality rate?", back: "Deaths from one specified cause during a period divided by the population, usually multiplied by a standard base.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-131", category: "Statistics", front: "What is an age-specific rate?", back: "A rate calculated for one age group, using that age group as the denominator.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-132", category: "Statistics", front: "What is the infant mortality rate?", back: "Deaths of infants under one year of age divided by live births, commonly reported per 1,000 live births.", source: "Disease Detectives wiki" },
  { id: "dd-133", category: "Statistics", front: "What is the case-fatality percentage?", back: "Deaths among people with the disease divided by all people with the disease, multiplied by 100.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-134", category: "Statistics", front: "What does an attack rate compare?", back: "The proportion who become ill among people exposed or otherwise at risk; compare attack rates between exposure groups to identify a possible source.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-135", category: "Statistics", front: "How do you calculate a food-specific attack rate?", back: "Number of people who ate the food and became ill divided by the total number of people who ate that food.", source: "Outbreak investigation" },
  { id: "dd-136", category: "Statistics", front: "How do you calculate an exposure-specific relative risk?", back: "Attack rate among people with the exposure divided by attack rate among people without the exposure.", source: "Outbreak investigation" },
  { id: "dd-137", category: "Statistics", front: "What does a risk difference of zero mean?", back: "The exposed and unexposed groups have the same risk; there is no absolute excess risk attributable to the exposure.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-138", category: "Statistics", front: "What does an odds ratio of one mean?", back: "The odds of exposure are the same among cases and controls; there is no measured association.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-139", category: "Statistics", front: "How can you tell if a confidence interval excludes the null?", back: "For ratios such as RR or OR, the null is 1. For differences, the null is 0. If the interval excludes the appropriate null, the result is statistically significant at the matching level.", source: "Statistics review" },
  { id: "dd-140", category: "Statistics", front: "What does a wide confidence interval suggest?", back: "The estimate is imprecise, often because the sample is small, the outcome is rare, or the data are highly variable.", source: "Statistics review" },
  { id: "dd-141", category: "Statistics", front: "What is precision vs. validity?", back: "Precision is consistency or narrow uncertainty; validity is closeness to the truth. A biased estimate can be precise but invalid.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-142", category: "Statistics", front: "What is random error?", back: "Variation caused by chance or sampling fluctuation; it can be reduced with larger samples but not reliably removed by increasing sample size alone if bias remains.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-143", category: "Statistics", front: "What is systematic error?", back: "A consistent deviation from the truth caused by bias in design, measurement, selection, or analysis.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-144", category: "Statistics", front: "Why does increasing sample size narrow a confidence interval?", back: "Larger samples reduce standard error, making the estimate more precise.", source: "Disease Detectives wiki" },
  { id: "dd-145", category: "Statistics", front: "What is a representative sample?", back: "A sample whose important characteristics reasonably reflect the target population; random selection helps but does not guarantee representativeness.", source: "Statistics review" },
  { id: "dd-146", category: "Statistics", front: "Simple random vs. convenience sampling", back: "Simple random sampling gives eligible members known chances of selection. Convenience sampling selects whoever is easiest to reach and is more vulnerable to selection bias.", source: "Study design review" },
  { id: "dd-147", category: "Statistics", front: "What is stratification?", back: "Dividing data into meaningful subgroups, such as age or sex, to describe patterns or control confounding.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-148", category: "Statistics", front: "What is effect modification?", back: "When the effect of an exposure genuinely differs across levels of another variable; unlike confounding, it should usually be reported rather than simply controlled away.", source: "Study design review" },
  { id: "dd-149", category: "Statistics", front: "What is direct standardization?", back: "Applying age-specific rates from study populations to one standard population distribution to create comparable adjusted rates.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-150", category: "Statistics", front: "What is indirect standardization?", back: "Applying standard rates to the study population to calculate expected events, then comparing observed with expected events.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-151", category: "Statistics", front: "What is a standardized mortality ratio (SMR)?", back: "Observed deaths divided by expected deaths, often multiplied by 100. An SMR above 100 means more deaths than expected.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-152", category: "Statistics", front: "What is a normal distribution?", back: "A symmetric, bell-shaped distribution in which mean, median, and mode coincide.", source: "Disease Detectives wiki" },
  { id: "dd-153", category: "Statistics", front: "What is a right-skewed distribution?", back: "A distribution with a long tail toward larger values; the mean is commonly greater than the median.", source: "Disease Detectives wiki" },
  { id: "dd-154", category: "Statistics", front: "When should median and IQR be preferred?", back: "For skewed data or data with influential outliers, because median and IQR are more resistant than mean and standard deviation.", source: "Disease Detectives wiki" },
  { id: "dd-155", category: "Statistics", front: "What is the interquartile range?", back: "Q3 − Q1, the range containing the middle 50% of observations.", source: "Disease Detectives wiki" },
  { id: "dd-156", category: "Statistics", front: "What is the 68–95–99.7 rule?", back: "For a normal distribution, about 68% lie within 1 SD, 95% within 2 SD, and 99.7% within 3 SD of the mean.", source: "Disease Detectives wiki" },
  { id: "dd-157", category: "Statistics", front: "What is a percentile?", back: "A value below which a specified percentage of observations fall; the 75th percentile has about 75% of observations at or below it.", source: "Statistics review" },
  { id: "dd-158", category: "Statistics", front: "What is an outlier?", back: "An observation unusually far from the rest of the data; investigate whether it reflects error, a different subgroup, or a real extreme.", source: "Disease Detectives wiki" },
  { id: "dd-159", category: "Statistics", front: "What does correlation coefficient r measure?", back: "The direction and strength of a linear relationship, ranging from −1 to +1; it does not prove causation and does not describe every nonlinear relationship.", source: "Disease Detectives wiki" },
  { id: "dd-160", category: "Statistics", front: "What does r = −0.90 suggest?", back: "A strong negative linear association: as one variable increases, the other tends to decrease. It is still not proof of causation.", source: "Disease Detectives wiki" },
  { id: "dd-161", category: "Statistics", front: "What is linear regression used for?", back: "Modeling or predicting a numerical outcome from one or more predictors and quantifying an estimated relationship.", source: "Statistics review" },
  { id: "dd-162", category: "Statistics", front: "What is R²?", back: "The proportion of variation in the outcome explained by a fitted regression model; it does not establish causality.", source: "Statistics review" },
  { id: "dd-163", category: "Statistics", front: "What is a case definition’s sensitivity tradeoff?", back: "A broad definition captures more true cases but may include false positives; a narrow definition is more specific but may miss cases.", source: "Outbreak investigation" },
  { id: "dd-164", category: "Statistics", front: "What is misclassification?", back: "Assigning an individual to the wrong exposure or outcome category, which can bias measures of association.", source: "Bias review" },
  { id: "dd-165", category: "Statistics", front: "What is differential misclassification?", back: "Measurement error differs between comparison groups, potentially biasing results in either direction.", source: "Bias review" },
  { id: "dd-166", category: "Statistics", front: "What is nondifferential misclassification?", back: "Measurement error is similar across groups; it often weakens an association, though the effect is not guaranteed in every situation.", source: "Bias review" },
  { id: "dd-167", category: "Statistics", front: "What is lead-time bias?", back: "Earlier detection makes survival time after diagnosis appear longer without actually extending the time of life.", source: "Bias review" },
  { id: "dd-168", category: "Statistics", front: "What is length-time bias?", back: "Screening is more likely to detect slower-progressing disease, making screened cases appear to have better outcomes.", source: "Bias review" },
  { id: "dd-169", category: "Statistics", front: "What is immortal time bias?", back: "A period during which the outcome cannot occur for a group because of how exposure or eligibility is defined, creating an artificial survival advantage.", source: "Bias review" },
  { id: "dd-170", category: "Statistics", front: "What is loss to follow-up bias?", back: "Bias caused when people who leave a study differ systematically from those who remain, especially if loss relates to exposure or outcome.", source: "Bias review" },
  { id: "dd-171", category: "Statistics", front: "What is observer or interviewer bias?", back: "Data collection differs because an observer or interviewer knows a participant’s exposure, outcome, or study hypothesis.", source: "Bias review" },
  { id: "dd-172", category: "Statistics", front: "What is blinding?", back: "Keeping participants, investigators, assessors, or analysts unaware of group assignment to reduce expectation and measurement bias.", source: "Study design review" },
  { id: "dd-173", category: "Statistics", front: "What is matching in a case-control study?", back: "Selecting controls with characteristics similar to cases for variables such as age or neighborhood; matching must be accounted for in analysis.", source: "Study design review" },
  { id: "dd-174", category: "Statistics", front: "What is selection of controls supposed to accomplish?", back: "Controls should represent the exposure distribution in the population that produced the cases, not simply people who are convenient to recruit.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-175", category: "Statistics", front: "What is a before-and-after study’s main weakness?", back: "Changes may reflect secular trends, seasonality, regression to the mean, or other events rather than the intervention.", source: "Study design review" },
  { id: "dd-176", category: "Statistics", front: "What is regression to the mean?", back: "Extreme measurements tend to be closer to average on repeat measurement, even without an intervention.", source: "Statistics review" },
  { id: "dd-177", category: "Statistics", front: "What is a time-series design?", back: "Repeated measurements over time used to examine trends or changes before and after an intervention.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-178", category: "Statistics", front: "What is seasonality?", back: "A repeating pattern of disease occurrence at particular times of year, which must be considered when interpreting trends.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-179", category: "Statistics", front: "What is secular trend?", back: "A long-term change in disease frequency over years or decades, distinct from short-term seasonal variation.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-180", category: "Statistics", front: "What is regression analysis unable to prove by itself?", back: "It cannot prove that a predictor causes the outcome; confounding, reverse causation, selection, and model error may remain.", source: "Statistics review" },
  { id: "dd-181", category: "Foundations", front: "Classical vs. clinical epidemiology", back: "Classical epidemiology focuses on population and community origins of health problems. Clinical epidemiology studies patients and improves diagnosis, treatment, and prognosis.", source: "Disease Detectives wiki" },
  { id: "dd-182", category: "Foundations", front: "Descriptive vs. analytic epidemiology", back: "Descriptive epidemiology describes who, where, and when. Analytic epidemiology tests hypotheses about why and how an outcome occurs.", source: "Disease Detectives wiki" },
  { id: "dd-183", category: "Foundations", front: "What is an opportunistic disease?", back: "A disease that causes illness when the host’s immune system is damaged or weakened.", source: "Disease Detectives wiki" },
  { id: "dd-184", category: "Foundations", front: "What is a nosocomial infection?", back: "An infection acquired in a healthcare or hospital setting.", source: "Disease Detectives wiki" },
  { id: "dd-185", category: "Foundations", front: "What is an iatrogenic illness?", back: "An illness unintentionally caused by medical treatment, medication, or a healthcare provider.", source: "Disease Detectives wiki" },
  { id: "dd-186", category: "Foundations", front: "Chronic vs. latent infection", back: "A chronic infection remains continuously present and detectable. A latent infection can remain dormant and reactivate later.", source: "Disease Detectives wiki" },
  { id: "dd-187", category: "Foundations", front: "What is an asymptomatic carrier?", back: "A person who is infected and may transmit an agent but shows no signs or symptoms.", source: "Disease Detectives wiki" },
  { id: "dd-188", category: "Foundations", front: "What is susceptibility?", back: "The extent to which a host can resist infection; a susceptible person is at risk of becoming infected.", source: "Disease Detectives wiki" },
  { id: "dd-189", category: "Foundations", front: "What is an etiology?", back: "The cause or origin of a disease or health condition.", source: "Disease Detectives wiki" },
  { id: "dd-190", category: "Foundations", front: "What is a determinant?", back: "Any factor that brings about a change in a health condition.", source: "Disease Detectives wiki" },
  { id: "dd-191", category: "Outbreaks", front: "What is the first step of an outbreak investigation?", back: "Prepare for field work: research the situation, gather supplies, arrange travel and administration, and establish roles and contacts.", source: "13 outbreak-investigation steps" },
  { id: "dd-192", category: "Outbreaks", front: "How do investigators establish that an outbreak exists?", back: "Compare observed cases with the expected baseline and consider severity, potential spread, public concern, and available resources.", source: "13 outbreak-investigation steps" },
  { id: "dd-193", category: "Outbreaks", front: "How are cases found systematically?", back: "Use healthcare reports, laboratory records, interviews, registries, active case finding, and a consistent case definition; record each case in a line list.", source: "13 outbreak-investigation steps" },
  { id: "dd-194", category: "Outbreaks", front: "What is descriptive epidemiology during an outbreak?", back: "Characterize cases by person, place, and time using case information, maps, tables, and an epidemic curve.", source: "13 outbreak-investigation steps" },
  { id: "dd-195", category: "Outbreaks", front: "What is a working hypothesis?", back: "A testable explanation about the agent, source, exposure, route, or population at risk that guides further investigation.", source: "13 outbreak-investigation steps" },
  { id: "dd-196", category: "Outbreaks", front: "Why reconcile epidemiologic and laboratory evidence?", back: "A plausible exposure pattern should agree with laboratory, clinical, and environmental findings before conclusions are finalized.", source: "13 outbreak-investigation steps" },
  { id: "dd-197", category: "Outbreaks", front: "What is active case finding?", back: "Health officials proactively contact providers, institutions, laboratories, or communities to locate additional cases.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-198", category: "Outbreaks", front: "What should a line list help investigators see?", back: "Patterns in symptoms, onset dates, exposures, locations, demographics, test results, and possible links among cases.", source: "Outbreak investigation" },
  { id: "dd-199", category: "Outbreaks", front: "What does a point-source curve suggest about exposure?", back: "Most cases were exposed during a relatively short, well-defined period; the incubation-period range can be estimated from the curve.", source: "Disease Detectives wiki" },
  { id: "dd-200", category: "Outbreaks", front: "What does the time between propagated peaks suggest?", back: "It may approximate the generation or incubation interval between successive rounds of person-to-person transmission.", source: "Disease Detectives wiki" },
  { id: "dd-201", category: "Outbreaks", front: "What is an intermittent common-source outbreak?", back: "Cases occur in multiple peaks because exposure from the common source happens irregularly.", source: "Disease Detectives wiki" },
  { id: "dd-202", category: "Outbreaks", front: "What is a point-source exposure window?", back: "The limited time during which people encountered the common source; compare it with the earliest and latest onset dates.", source: "Outbreak investigation" },
  { id: "dd-203", category: "Study Design", front: "Prospective vs. retrospective cohort", back: "Prospective cohorts follow participants forward from exposure. Retrospective cohorts use existing records to reconstruct exposure and subsequent outcome.", source: "Question Marathon" },
  { id: "dd-204", category: "Study Design", front: "What is a randomized controlled trial?", back: "An experiment in which participants are randomly assigned to intervention or control groups and outcomes are compared.", source: "Disease Detectives wiki" },
  { id: "dd-205", category: "Study Design", front: "What is a quasi-experiment?", back: "An intervention study without random assignment; groups are formed by nonrandom criteria, so confounding is a concern.", source: "Disease Detectives wiki" },
  { id: "dd-206", category: "Study Design", front: "Ecological vs. cross-sectional study", back: "Ecological studies compare groups, not individuals. Cross-sectional studies measure exposure and outcome in individuals at one point in time.", source: "Disease Detectives wiki" },
  { id: "dd-207", category: "Study Design", front: "What is temporality’s role in study design?", back: "A valid causal explanation requires exposure to occur before the outcome; cross-sectional designs often cannot establish this sequence.", source: "Study design review" },
  { id: "dd-208", category: "Bias", front: "What is information bias?", back: "Systematic error from inaccurate or incomplete information about exposure, outcome, or other variables.", source: "Disease Detectives wiki" },
  { id: "dd-209", category: "Bias", front: "What is performance bias?", back: "Bias caused when researchers or participants change behavior because they know which group or intervention is involved.", source: "Disease Detectives wiki" },
  { id: "dd-210", category: "Bias", front: "What is reporting bias?", back: "A systematic difference in which results are reported, emphasized, or made available.", source: "Disease Detectives wiki" },
  { id: "dd-211", category: "Bias", front: "What is measurement bias?", back: "Bias caused by inaccurate instruments, procedures, observers, or measurement methods.", source: "Disease Detectives wiki" },
  { id: "dd-212", category: "Bias", front: "What is a confounder’s three-part pattern?", back: "It is associated with the exposure, is a risk factor for the outcome, and is not an intermediate step in the causal pathway.", source: "Study design review" },
  { id: "dd-213", category: "Surveillance", front: "What is passive surveillance’s main limitation?", back: "Incomplete or delayed reporting and variation in reporting quality because agencies depend on routine provider reports.", source: "Disease Detectives wiki" },
  { id: "dd-214", category: "Surveillance", front: "When is active surveillance especially useful?", back: "During a specific investigation or outbreak when more complete and timely reporting is needed.", source: "Disease Detectives wiki" },
  { id: "dd-215", category: "Surveillance", front: "What is event-based surveillance?", back: "Monitoring reports, rumors, media, hotlines, or other signals for unusual health events that may need verification.", source: "Public-health surveillance review" },
  { id: "dd-216", category: "Surveillance", front: "What is a sentinel site’s advantage?", back: "Selected high-quality reporting sites can reveal trends early without requiring complete reporting from every provider.", source: "Disease Detectives wiki" },
  { id: "dd-217", category: "Surveillance", front: "What is surveillance data dissemination?", back: "Distributing interpreted findings through reports, alerts, briefings, articles, or media to people who can act.", source: "Disease Detectives wiki" },
  { id: "dd-218", category: "Surveillance", front: "Why is the link to action essential?", back: "Surveillance has public-health value only when information leads to prevention, control, resource allocation, or evaluation.", source: "Disease Detectives wiki" },
  { id: "dd-219", category: "Surveillance", front: "What does PulseNet do after a DNA pattern is uploaded?", back: "Microbiologists and epidemiologists search for matching patterns; clusters can trigger interviews and source investigations.", source: "Disease Detectives wiki" },
  { id: "dd-220", category: "Surveillance", front: "Why did PulseNet move from PFGE to WGS?", back: "Whole-genome sequencing provides a more detailed and precise comparison of pathogen genomes than PFGE.", source: "Disease Detectives wiki" },
  { id: "dd-221", category: "Transmission", front: "What is a portal of exit?", back: "The route an agent leaves a reservoir, such as the respiratory tract, gastrointestinal tract, skin, blood, or genital tract.", source: "Disease Detectives wiki" },
  { id: "dd-222", category: "Transmission", front: "What is a portal of entry?", back: "An opening or route through which an agent enters a host, commonly a respiratory or other mucous membrane.", source: "Disease Detectives wiki" },
  { id: "dd-223", category: "Transmission", front: "Droplet vs. airborne transmission", back: "Droplets travel short distances in larger respiratory particles; airborne transmission involves smaller particles or droplet nuclei that remain suspended longer.", source: "Disease Detectives wiki" },
  { id: "dd-224", category: "Transmission", front: "What is a fomite?", back: "An inanimate object that can carry an infectious agent and contribute to indirect-contact transmission.", source: "Disease Detectives wiki" },
  { id: "dd-225", category: "Transmission", front: "What is a biological vector?", back: "A living carrier in which the infectious agent multiplies or undergoes a developmental change.", source: "Disease Detectives wiki" },
  { id: "dd-226", category: "Transmission", front: "What is a mechanical vector?", back: "A living carrier that passively transports an agent without the agent multiplying or changing inside it.", source: "Disease Detectives wiki" },
  { id: "dd-227", category: "Transmission", front: "What is zoonotic transmission?", back: "Transmission of an infectious agent between animals and humans, in either direction depending on the disease.", source: "Disease Detectives wiki" },
  { id: "dd-228", category: "Transmission", front: "What is the reservoir of a disease?", back: "The natural habitat or source in which an agent normally lives and multiplies; it may be human, animal, or environmental.", source: "Disease Detectives wiki" },
  { id: "dd-229", category: "Immunity", front: "How does vaccination interrupt transmission?", back: "It increases immunity in hosts, reducing susceptibility and the number of opportunities for an agent to reach another susceptible host.", source: "Disease Detectives wiki" },
  { id: "dd-230", category: "Immunity", front: "What is naturally acquired passive immunity?", back: "Short-term transfer of maternal antibodies to a fetus or infant, such as through the placenta or breast milk.", source: "Disease Detectives wiki" },
  { id: "dd-231", category: "Immunity", front: "What is artificially acquired passive immunity?", back: "Short-term protection from injected or infused antibodies, such as immune globulin or monoclonal antibodies.", source: "Disease Detectives wiki" },
  { id: "dd-232", category: "Immunity", front: "What is the herd-immunity threshold assumption?", back: "The simple formula assumes a randomly mixing population and a vaccine that is 100% effective; real conditions can differ.", source: "Disease Detectives wiki" },
  { id: "dd-233", category: "Prevention", front: "What is primary prevention?", back: "Action taken before disease begins to prevent initial exposure or infection, such as vaccination or safe food handling.", source: "Disease Detectives wiki" },
  { id: "dd-234", category: "Prevention", front: "What is secondary prevention?", back: "Screening and early treatment during latent disease to prevent progression or complications.", source: "Disease Detectives wiki" },
  { id: "dd-235", category: "Prevention", front: "What is tertiary prevention?", back: "Treatment or rehabilitation during symptomatic disease to slow progression, reduce disability, or prevent complications.", source: "Disease Detectives wiki" },
  { id: "dd-236", category: "Prevention", front: "What is primordial prevention?", back: "Preventing the development of risk factors by changing social, physical, or environmental conditions.", source: "Disease Detectives wiki" },
  { id: "dd-237", category: "Prevention", front: "What is quaternary prevention?", back: "Reducing harm from unnecessary or excessive medical intervention and avoiding overdiagnosis or overtreatment.", source: "Disease Detectives wiki" },
  { id: "dd-238", category: "Foodborne", front: "What does FAT TOM’s ‘time’ factor mean?", back: "Foodborne organisms can multiply when food remains in favorable conditions too long; prompt chilling or heating limits growth.", source: "Disease Detectives wiki" },
  { id: "dd-239", category: "Foodborne", front: "What does FAT TOM’s ‘temperature’ factor mean?", back: "Many pathogens grow in the food temperature danger zone, approximately 41–135°F (5–57°C), with faster growth at favorable temperatures.", source: "Disease Detectives wiki" },
  { id: "dd-240", category: "Foodborne", front: "Why does cross-contamination matter?", back: "Pathogens can transfer from raw food, hands, equipment, or surfaces to ready-to-eat food that will not receive another kill step.", source: "Disease Detectives wiki" },
  { id: "dd-241", category: "CDC Core", front: "CDC Lesson 1: What are the two major branches of epidemiology?", back: "Descriptive epidemiology characterizes disease by person, place, and time. Analytic epidemiology tests hypotheses about causes and associations.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-242", category: "CDC Core", front: "What is the epidemiologic triad?", back: "Agent, host, and environment: the three interacting factors that influence whether disease occurs.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-243", category: "CDC Core", front: "What is the agent-host-environment model used for?", back: "Organizing possible causes and explaining how changes in the pathogen, host, or surroundings can alter disease occurrence.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-244", category: "CDC Core", front: "What are the characteristics of an agent?", back: "Infectivity, pathogenicity, virulence, antigenicity, and other properties that affect transmission and disease severity.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-245", category: "CDC Core", front: "What are host factors?", back: "Characteristics such as age, sex, genetics, immune status, nutrition, behavior, and occupation that affect susceptibility or outcome.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-246", category: "CDC Core", front: "What are environmental factors?", back: "External conditions such as climate, geography, housing, sanitation, crowding, vectors, and access to healthcare that influence disease.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-247", category: "CDC Core", front: "What is the chain of infection?", back: "The sequence linking agent, reservoir, portal of exit, mode of transmission, portal of entry, and susceptible host.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-248", category: "CDC Core", front: "What is a reservoir?", back: "The habitat in which an infectious agent normally lives, grows, and multiplies.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-249", category: "CDC Core", front: "What is a vehicle of transmission?", back: "An inanimate medium such as food, water, air, blood, or a contaminated object that carries an agent.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-250", category: "CDC Core", front: "What is a host’s incubation period?", back: "The interval between exposure to an infectious agent and onset of signs or symptoms.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-251", category: "CDC Core", front: "What is a pandemic?", back: "An epidemic that spreads across countries or continents and affects a large number of people.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-252", category: "CDC Core", front: "What is endemic disease?", back: "The constant or usual presence of a disease or infectious agent within a geographic population or season.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-253", category: "CDC Core", front: "What is hyperendemic disease?", back: "Persistently high occurrence of a disease in a population or geographic area.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-254", category: "CDC Core", front: "What is sporadic disease?", back: "A disease that occurs infrequently and irregularly, with cases scattered in time and place.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-255", category: "CDC Core", front: "What is a secular trend?", back: "A long-term pattern of disease occurrence over years or decades.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-256", category: "CDC Core", front: "What is seasonality?", back: "A pattern of disease occurrence that repeats at particular seasons or times of year.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-257", category: "CDC Core", front: "What is a point epidemic?", back: "A cluster of cases resulting from exposure to a common source over a relatively short period.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-258", category: "CDC Core", front: "What does person-place-time analysis ask?", back: "Who is affected, where are cases occurring, and when are cases occurring or increasing?", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-259", category: "CDC Core", front: "Why use rates instead of only case counts?", back: "Rates account for population size and allow fairer comparisons between groups or locations of different sizes.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-260", category: "CDC Core", front: "What is the numerator in a rate?", back: "The number of events or cases being measured during the specified period.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-261", category: "CDC Core", front: "What is the denominator in a rate?", back: "The population or person-time from which the cases arose and in which the population was at risk.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-262", category: "CDC Core", front: "What makes a denominator inappropriate?", back: "It excludes people who could have experienced the event, includes people outside the source population, or uses a mismatched time period.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-263", category: "CDC Core", front: "What is a proportionate mortality ratio?", back: "Deaths from a specified cause divided by deaths from all causes during a time period, expressed as a percentage.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-264", category: "CDC Core", front: "What is a crude mortality rate unlike a proportionate mortality ratio?", back: "A mortality rate uses the population as its denominator; a proportionate mortality ratio uses all deaths as its denominator.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-265", category: "CDC Core", front: "What is a survival rate?", back: "The proportion of people in a defined group who remain alive for a specified period after a starting point such as diagnosis.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-266", category: "CDC Core", front: "What is a case definition?", back: "A standardized set of criteria used to decide whether a person should be classified as having a disease or health event.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-267", category: "CDC Core", front: "Why should a case definition not include the suspected exposure?", back: "Including the exposure can build the hypothesis into the definition and bias case finding; first define the health outcome consistently.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-268", category: "CDC Core", front: "What is an outbreak case classification?", back: "A system such as confirmed, probable, and suspect/possible that reflects differing levels of clinical, epidemiologic, and laboratory evidence.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-269", category: "CDC Core", front: "What is active surveillance?", back: "A surveillance system in which health personnel actively seek reports from providers, laboratories, or institutions.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-270", category: "CDC Core", front: "What is passive surveillance?", back: "Routine reporting by healthcare providers, laboratories, or institutions without active prompting for every case.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-271", category: "CDC Core", front: "What is sentinel surveillance?", back: "Surveillance using selected reporting sites or providers to monitor trends or provide early warning.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-272", category: "CDC Core", front: "What is syndromic surveillance?", back: "Using symptom patterns, clinical observations, or proxies before definitive diagnosis to detect possible outbreaks quickly.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-273", category: "CDC Core", front: "What are key attributes of a surveillance system?", back: "Simplicity, flexibility, data quality, acceptability, sensitivity, predictive value positive, representativeness, timeliness, and stability.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-274", category: "CDC Core", front: "What is surveillance sensitivity?", back: "The ability of a surveillance system to detect cases or outbreaks that actually occur.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-275", category: "CDC Core", front: "What is surveillance timeliness?", back: "The speed between a health event, its detection/reporting, and the availability of information for action.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-276", category: "CDC Core", front: "What is a surveillance case definition used for?", back: "Consistent classification and counting of cases across people, places, and time; it is not necessarily a clinical diagnosis.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-277", category: "CDC Core", front: "What is a descriptive table?", back: "A structured display of counts, rates, or percentages that makes comparisons and patterns easier to see.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-278", category: "CDC Core", front: "What should every public-health graph label?", back: "The outcome, population or groups, time/place when relevant, units, scale, and data source or denominator.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-279", category: "CDC Core", front: "What is an epi curve’s x-axis and y-axis?", back: "The x-axis shows time of onset or another time variable; the y-axis shows number of cases, and sometimes a rate when appropriate.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-280", category: "CDC Core", front: "What can an epi curve reveal?", back: "The likely outbreak pattern, possible exposure period, incubation interval, outliers, and whether transmission is continuing.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-281", category: "CDC Core", front: "What is a spot map’s limitation?", back: "It shows where cases occur but not necessarily the population at risk, exposure denominators, or statistical significance of a cluster.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-282", category: "CDC Core", front: "What is a line list’s purpose in an outbreak?", back: "To organize individual-level information so investigators can monitor cases, identify patterns, and update the investigation.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-283", category: "CDC Core", front: "What is the first analytic step after describing an outbreak?", back: "Develop a specific, testable hypothesis about the likely source, vehicle, mode of transmission, and population at risk.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-284", category: "CDC Core", front: "What is an analytic epidemiologic study during an outbreak?", back: "A comparison of groups, such as exposed and unexposed or ill and well, to evaluate whether an exposure is associated with illness.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-285", category: "CDC Core", front: "When is a cohort study especially practical during an outbreak?", back: "When the exposed population is well-defined, such as everyone at a meal, event, school, workplace, or household.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-286", category: "CDC Core", front: "When is a case-control study especially practical during an outbreak?", back: "When the source population is unclear, the disease is rare, or investigators need an efficient comparison of cases and controls.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-287", category: "CDC Core", front: "What is an environmental investigation?", back: "Inspection, sampling, observation, and record review used to identify contamination, exposure pathways, or conditions supporting transmission.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-288", category: "CDC Core", front: "Why collect specimens from both people and the environment?", back: "Matching laboratory results can connect a pathogen in patients to a suspected source, vehicle, or setting.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-289", category: "CDC Core", front: "What is a hypothesis-generating interview?", back: "An open-ended interview that gathers detailed information about activities, foods, locations, contacts, and timing before a standardized questionnaire is finalized.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-290", category: "CDC Core", front: "What is a hypothesis-testing questionnaire?", back: "A standardized instrument that measures suspected exposures consistently among cases, controls, or cohort members.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-291", category: "CDC Core", front: "What is the epidemic threshold?", back: "The level of disease occurrence above which an outbreak or epidemic is suspected relative to the expected baseline.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-292", category: "CDC Core", front: "What is a baseline level?", back: "The usual amount or pattern of disease in a population during a comparable period, used to identify unusual increases.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-293", category: "CDC Core", front: "What is a public-health recommendation after an investigation?", back: "A practical control or prevention action tied to evidence, feasibility, timing, communication, and evaluation.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-294", category: "CDC Core", front: "Why communicate preliminary findings carefully?", back: "Information can change as more data arrive; clear uncertainty prevents misinformation while still supporting timely protective action.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-295", category: "CDC Core", front: "What is evaluation in surveillance?", back: "A periodic assessment of whether the system meets its objectives and whether data are useful, timely, accurate, and actionable.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-296", category: "CDC Core", front: "What is a data quality problem?", back: "Missing, invalid, duplicate, inconsistent, delayed, or incorrectly classified data that can distort descriptive and analytic conclusions.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-297", category: "CDC Core", front: "What is denominator data used for in surveillance?", back: "Population counts provide the base for calculating rates and comparing disease occurrence between groups or areas.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-298", category: "CDC Core", front: "Why compare rates by age?", back: "Age distributions can differ between populations and age strongly affects risk; age-specific or adjusted rates can prevent misleading comparisons.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-299", category: "CDC Core", front: "What is the CDC’s outbreak-investigation sequence at a high level?", back: "Prepare, verify the outbreak and diagnosis, define and find cases, describe by person/place/time, develop and test hypotheses, implement control, maintain surveillance, and communicate findings.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-300", category: "CDC Core", front: "What is the central goal of applied epidemiology?", back: "Use valid, timely evidence to prevent disease, control outbreaks, protect populations, and improve public-health decisions.", source: "CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-301", category: "Foundations", front: "Endemic, epidemic, and sporadic disease occurrence", back: "Endemic disease is consistently present at an expected level; an epidemic exceeds that baseline; sporadic cases occur irregularly and infrequently.", source: "Disease Detectives wiki; CDC Principles of Epidemiology, Lesson 1" },
  { id: "dd-302", category: "Foundations", front: "R0 versus effective reproduction number", back: "R0 is the average number of secondary cases produced in a fully susceptible population; the effective reproduction number reflects current immunity and conditions.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-303", category: "Foundations", front: "What is the serial interval?", back: "The time between symptom onset in a primary case and symptom onset in a secondary case infected by that person.", source: "Question Marathon" },
  { id: "dd-304", category: "Foundations", front: "Why can a disease spread when R0 is above 1 but stop when the effective reproduction number falls below 1?", back: "Each case produces more than one case on average when R is above 1, but immunity, behavior, or control measures can reduce average transmission below replacement.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-305", category: "Foundations", front: "A pathogen is detected before symptoms in many cases. Which timing interval should investigators examine?", back: "The latent period and presymptomatic infectious period, not only the incubation period, because transmission can begin before symptoms.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-306", category: "Outbreaks", front: "A restaurant curve rises sharply to one peak and then declines after one meal. What pattern is most likely?", back: "A point-source common exposure; the narrow peak suggests many people were exposed during a short interval.", source: "Disease Detectives wiki; CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-307", category: "Outbreaks", front: "How can an investigator estimate a point-source exposure window from an epi curve?", back: "Work backward from the earliest and latest onset dates using the suspected disease's minimum and maximum incubation periods, then look for shared exposures.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-308", category: "Outbreaks", front: "A curve has peaks separated by roughly one incubation period. What does that suggest?", back: "Propagated person-to-person transmission, with successive generations of cases rather than one simultaneous exposure.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-309", category: "Outbreaks", front: "Why should a case definition be specific before calculating an attack rate?", back: "A stable numerator ensures cases are classified consistently; changing clinical, time, or place criteria changes the denominator and makes comparisons misleading.", source: "13 outbreak-investigation steps; CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-310", category: "Outbreaks", front: "A school reports 12 students with vomiting, but no baseline is available. What should investigators do first?", back: "Verify the diagnosis and compare with expected illness, then begin descriptive case finding while obtaining historical attendance and illness data.", source: "13 outbreak-investigation steps; CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-311", category: "Study Design", front: "Why is a cohort study efficient after a defined banquet exposure?", back: "The entire exposed group can be enumerated, so investigators can compare illness among people who ate each food and calculate attack rates and relative risks.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-312", category: "Study Design", front: "A case-control study has 40 cases and 80 controls. Why can it not directly calculate incidence?", back: "The investigator selected participants by outcome, so the case and control counts do not represent the population at risk; an odds ratio is appropriate.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-313", category: "Study Design", front: "What is a prospective cohort study?", back: "Participants are classified by exposure before the outcome occurs and followed forward to compare new disease in exposure groups.", source: "Question Marathon" },
  { id: "dd-314", category: "Study Design", front: "How does randomization help an intervention study?", back: "It tends to distribute known and unknown confounders between groups, making outcome differences more attributable to the intervention.", source: "Disease Detectives wiki" },
  { id: "dd-315", category: "Study Design", front: "How can matching reduce confounding in a case-control study?", back: "Selecting controls with characteristics such as age or neighborhood similar to cases to reduce confounding by those variables.", source: "Disease Detectives wiki" },
  { id: "dd-316", category: "Study Design", front: "What is an ecological study?", back: "A study comparing exposure and outcome measurements for groups or populations rather than linked individual participants.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-317", category: "Study Design", front: "Why can a cross-sectional survey show association but not establish temporality?", back: "Exposure and outcome are measured at the same time, so it may be unclear whether exposure preceded disease or disease changed the exposure.", source: "Disease Detectives wiki" },
  { id: "dd-318", category: "Bias", front: "What is interviewer bias?", back: "Systematic differences in how an interviewer questions or records information from study participants, potentially related to their case status or hypothesis.", source: "Disease Detectives wiki" },
  { id: "dd-319", category: "Bias", front: "What is misclassification bias?", back: "Systematic incorrect assignment of exposure, disease, or case status; nondifferential and differential misclassification can affect estimates differently.", source: "Disease Detectives wiki" },
  { id: "dd-320", category: "Bias", front: "How can blinding reduce bias?", back: "Keeping participants, investigators, or outcome assessors unaware of exposure or treatment assignment can reduce differential reporting or assessment.", source: "Disease Detectives wiki" },
  { id: "dd-321", category: "Statistics", front: "An outbreak has 30 cases among 200 people who ate salad and 10 cases among 250 who did not. What is the relative risk?", back: "Risk exposed = 30/200 = 0.15; risk unexposed = 10/250 = 0.04; relative risk = 0.15/0.04 = 3.75.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-322", category: "Statistics", front: "Using the salad data, what is the attributable risk among exposed people?", back: "Attributable risk = 0.15 - 0.04 = 0.11, or 11 excess cases per 100 exposed people during the outbreak period.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-323", category: "Statistics", front: "A 2x2 table has a=18, b=42, c=6, and d=54. What is the odds ratio?", back: "OR = (a x d)/(b x c) = (18 x 54)/(42 x 6) = 3.86, approximately.", source: "Disease Detectives wiki; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-324", category: "Statistics", front: "What does a relative risk of 1 mean?", back: "The measured risk is the same in exposed and unexposed groups; it shows no association on that measure, though bias or imprecision may remain.", source: "Disease Detectives wiki" },
  { id: "dd-325", category: "Statistics", front: "What does a relative risk below 1 suggest?", back: "The exposure is associated with lower risk than the comparison group; investigators must still assess causation, confounding, and the confidence interval.", source: "Disease Detectives wiki" },
  { id: "dd-326", category: "Statistics", front: "What fraction of exposed-group risk is attributable to the exposure?", back: "The proportion of disease among exposed people attributable to the exposure: (risk exposed - risk unexposed) / risk exposed.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-327", category: "Statistics", front: "If an exposure risk is 0.20 and the unexposed risk is 0.05, what is the attributable fraction among exposed?", back: "(0.20 - 0.05) / 0.20 = 0.75, so 75% of risk among exposed people is attributable to the exposure under the causal assumptions.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-328", category: "Statistics", front: "How should a 95% confidence interval for a relative risk of 1.4 with limits 0.9 to 2.1 be interpreted?", back: "The point estimate suggests higher risk, but the interval includes 1, so the association is not statistically distinguishable from no association at the corresponding two-sided 0.05 level.", source: "Disease Detectives wiki" },
  { id: "dd-329", category: "Statistics", front: "What does a narrow confidence interval indicate?", back: "Greater statistical precision around the estimate, often from more information or less variability; it does not guarantee absence of systematic bias.", source: "Disease Detectives wiki" },
  { id: "dd-330", category: "Statistics", front: "How does statistical power relate to a Type II error?", back: "Power is the probability of detecting an effect of a specified size when it truly exists; low power increases the chance of a Type II error.", source: "Question Marathon" },
  { id: "dd-331", category: "Statistics", front: "How can you recognize effect modification rather than confounding?", back: "A real difference in an exposure-outcome association across levels of a third variable, such as different risks in children and adults.", source: "Disease Detectives wiki" },
  { id: "dd-332", category: "Statistics", front: "How does stratification help investigate confounding?", back: "Calculate exposure-outcome estimates within levels of the suspected confounder and compare them with the crude estimate.", source: "Disease Detectives wiki" },
  { id: "dd-333", category: "Statistics", front: "Why are rates more useful than case counts for comparing counties?", back: "Rates use population denominators, so they account for different population sizes and make disease occurrence more comparable.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-334", category: "Statistics", front: "A county reports 45 cases in a population of 90,000. What is the rate per 100,000?", back: "(45 / 90,000) x 100,000 = 50 cases per 100,000 population.", source: "Question Marathon; CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-335", category: "Statistics", front: "Why can a crude mortality rate mislead when two populations have different age structures?", back: "Older populations may have higher crude mortality simply because age-specific risks differ; age-standardized rates allow a fairer comparison.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-336", category: "Surveillance", front: "What is case-based surveillance?", back: "Collection of information about individual persons meeting a defined condition, rather than only aggregated totals.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-337", category: "Surveillance", front: "What is a notifiable condition?", back: "A condition that public-health authorities require or request providers and laboratories to report under specified rules.", source: "Disease Detectives wiki; CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-338", category: "Surveillance", front: "How do sensitivity and timeliness trade off in surveillance?", back: "A highly sensitive system may detect more possible cases but create more false signals; faster reporting can sacrifice completeness or confirmation.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-339", category: "Surveillance", front: "What is an outbreak signal?", back: "A data pattern suggesting disease occurrence is above expected levels or has an unusual time, place, host, or laboratory profile.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-340", category: "Surveillance", front: "Why should a surveillance system track its denominator?", back: "Without the population under observation, counts cannot be converted into comparable rates or interpreted as changing risk.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-341", category: "Transmission", front: "Which infection-chain link describes how an agent leaves a host?", back: "The route by which an infectious agent leaves its reservoir or host, such as the respiratory tract, blood, or gastrointestinal tract.", source: "Disease Detectives wiki" },
  { id: "dd-342", category: "Transmission", front: "Which infection-chain link describes how an agent enters a new host?", back: "The route through which an infectious agent enters a new host, such as mucous membranes, broken skin, or the respiratory tract.", source: "Disease Detectives wiki" },
  { id: "dd-343", category: "Transmission", front: "What is fomites transmission?", back: "Indirect contact transmission through contaminated objects or surfaces that transfer an infectious agent.", source: "Disease Detectives wiki" },
  { id: "dd-344", category: "Transmission", front: "Why can hand hygiene interrupt more than one chain-of-infection link?", back: "It can remove an agent from hands, prevent transfer from a reservoir or vehicle, and block entry to the mouth, nose, eyes, or another host.", source: "Disease Detectives wiki" },
  { id: "dd-345", category: "Transmission", front: "What is a zoonotic disease?", back: "A disease caused by an infectious agent that naturally circulates between animals and humans, with transmission sometimes involving a vector or vehicle.", source: "Disease Detectives wiki" },
  { id: "dd-346", category: "Immunity", front: "What is vaccine effectiveness?", back: "The reduction in disease among vaccinated people under real-world conditions compared with an appropriate unvaccinated comparison.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-347", category: "Immunity", front: "How is vaccine effectiveness calculated from relative risk?", back: "VE = (1 - relative risk) x 100%, where relative risk compares disease risk in vaccinated and unvaccinated groups.", source: "Question Marathon" },
  { id: "dd-348", category: "Immunity", front: "Vaccinated people have risk 0.02 and unvaccinated people risk 0.08. What is vaccine effectiveness?", back: "VE = (1 - 0.02/0.08) x 100% = 75%.", source: "Question Marathon; Disease Detectives wiki" },
  { id: "dd-349", category: "Immunity", front: "What is a breakthrough infection?", back: "An infection occurring in a person who has some vaccine- or infection-derived protection; it may be less severe without being impossible.", source: "Disease Detectives wiki" },
  { id: "dd-350", category: "Immunity", front: "Why does herd immunity vary by pathogen?", back: "The required immune proportion depends on transmission potential, represented in a simple model by 1 - 1/R0, and on immunity effectiveness and durability.", source: "Disease Detectives wiki; Question Marathon" },
  { id: "dd-351", category: "Prevention", front: "What is a critical control point in food safety?", back: "A step where a hazard can be prevented, eliminated, or reduced to an acceptable level, such as adequate cooking or chilling.", source: "Foodborne illness review" },
  { id: "dd-352", category: "Prevention", front: "Why is preventing cross-contamination a different control from cooking?", back: "Cooking can kill organisms already in food, while separation prevents transfer from raw food, hands, utensils, or surfaces to ready-to-eat food.", source: "Foodborne illness review" },
  { id: "dd-353", category: "Prevention", front: "A food sample is positive but no diners are ill. What conclusion is justified?", back: "The sample indicates contamination or hazard, but illness absence may reflect dose, timing, susceptibility, or limited detection; it does not prove causation.", source: "Foodborne illness review; Question Marathon" },
  { id: "dd-354", category: "Prevention", front: "What is source control?", back: "An intervention that removes or reduces the origin of exposure, such as closing a contaminated well, recalling food, or treating an infected reservoir.", source: "Disease Detectives wiki" },
  { id: "dd-355", category: "Prevention", front: "How is contact tracing used after a case is identified?", back: "Interview the case, identify exposed contacts and timing, notify them, recommend testing or quarantine when appropriate, and monitor for symptoms.", source: "Disease Detectives wiki; 13 outbreak-investigation steps" },
  { id: "dd-356", category: "Causation", front: "Why is temporality necessary but not sufficient for causation?", back: "A cause must precede an outcome, but many exposures precede disease by chance or through confounding without causing it.", source: "Hill’s criteria review" },
  { id: "dd-357", category: "Causation", front: "What is biological plausibility in Hill's criteria?", back: "The proposed relationship is compatible with established biological mechanisms, while recognizing that lack of current knowledge does not automatically disprove causation.", source: "Hill’s criteria review" },
  { id: "dd-358", category: "Causation", front: "What does consistency mean in Hill's criteria?", back: "Similar exposure-outcome findings occur across different studies, populations, places, or methods.", source: "Hill’s criteria review" },
  { id: "dd-359", category: "Causation", front: "Why can specificity be weak evidence for many infectious diseases?", back: "One agent may cause several outcomes and one outcome may have multiple causes, so a lack of one-to-one specificity does not exclude causation.", source: "Hill’s criteria review" },
  { id: "dd-360", category: "Causation", front: "What is an alternative explanation in an outbreak hypothesis?", back: "Another source, exposure, measurement process, or chance pattern that could account for the observed cases without the proposed cause.", source: "13 outbreak-investigation steps; Question Marathon" },
  { id: "dd-361", category: "CDC Core", front: "Why preserve the original data dictionary during an outbreak?", back: "It records variable definitions, coding, units, and missing-value rules so analyses remain reproducible as the line list changes.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-362", category: "CDC Core", front: "What is a denominator at risk?", back: "The people who are susceptible, exposed to the relevant setting, and eligible to become cases during the specified period.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-363", category: "CDC Core", front: "Why exclude already ill people from the denominator for a secondary attack rate?", back: "They were not susceptible contacts at the start of the secondary exposure period, so including them understates the risk among contacts who could become cases.", source: "CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-364", category: "CDC Core", front: "What is a spot map best suited to identify?", back: "Geographic clustering or a possible common source, while requiring population and exposure data before inferring excess risk.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-365", category: "CDC Core", front: "What does a right-skewed distribution imply for choosing a summary statistic?", back: "The mean may be pulled toward high values, so the median and interquartile range can better describe the typical observation.", source: "CDC Principles of Epidemiology, Lesson 2" },
  { id: "dd-366", category: "CDC Core", front: "What is an outlier on an epi curve?", back: "A case whose onset is unusually early or late relative to the main pattern; it may represent a separate exposure, reporting error, or a different incubation interval.", source: "CDC Principles of Epidemiology, Lesson 4" },
  { id: "dd-367", category: "CDC Core", front: "Why should investigators compare laboratory methods across time?", back: "A change in test sensitivity, case definition, or testing volume can create an apparent increase unrelated to a true change in disease occurrence.", source: "CDC Principles of Epidemiology, Lesson 5" },
  { id: "dd-368", category: "CDC Core", front: "A public-health intervention lowers reported cases but also reduces testing. What must be considered?", back: "The decline may reflect ascertainment or surveillance changes rather than control success; use multiple indicators and document testing volume.", source: "CDC Principles of Epidemiology, Lesson 5; Question Marathon" },
  { id: "dd-369", category: "CDC Core", front: "What makes an outbreak control measure evidence-based?", back: "It targets a supported transmission link or source, is feasible and timely, accounts for harms and equity, and is evaluated with appropriate outcome data.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-370", category: "CDC Core", front: "Why should an outbreak report distinguish facts, interpretations, and recommendations?", back: "Separating observations from inferences and proposed actions makes uncertainty visible and lets readers evaluate how evidence supports decisions.", source: "CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-371", category: "Question Marathon", front: "A case definition becomes more sensitive but less specific. What happens to case counts?", back: "More true cases may be captured, but more non-cases may also be included; the apparent attack rate can rise because of classification changes.", source: "Disease Detectives Question Marathon; CDC Principles of Epidemiology, Lesson 6" },
  { id: "dd-372", category: "Question Marathon", front: "In a cohort, 8 of 40 exposed people and 6 of 60 unexposed people become ill. What is the relative risk?", back: "Risk exposed = 0.20; risk unexposed = 0.10; relative risk = 2.0.", source: "Disease Detectives Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-373", category: "Question Marathon", front: "In the same cohort, what is the attributable risk among exposed people?", back: "0.20 - 0.10 = 0.10, or 10 percentage points of excess risk among exposed people.", source: "Disease Detectives Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-374", category: "Question Marathon", front: "A diagnostic test has 90 true positives and 10 false negatives among diseased people. What is sensitivity?", back: "90 / (90 + 10) = 90%.", source: "Disease Detectives Question Marathon; Disease Detectives wiki" },
  { id: "dd-375", category: "Question Marathon", front: "A test has 180 true negatives and 20 false positives among disease-free people. What is specificity?", back: "180 / (180 + 20) = 90%.", source: "Disease Detectives Question Marathon; Disease Detectives wiki" },
  { id: "dd-376", category: "Question Marathon", front: "Why does positive predictive value change when prevalence changes?", back: "Predictive value depends on the proportion diseased before testing; at lower prevalence, false positives can make up a larger fraction of positive results.", source: "Disease Detectives Question Marathon; Disease Detectives wiki" },
  { id: "dd-377", category: "Question Marathon", front: "A household has one primary case and 4 susceptible contacts; 2 contacts become ill. What is the secondary attack rate?", back: "2 / 4 = 50%, assuming those contacts were susceptible and observed for the full relevant period.", source: "Disease Detectives Question Marathon; CDC Principles of Epidemiology, Lesson 3" },
  { id: "dd-378", category: "Question Marathon", front: "Why can a statistically significant association still be poor evidence for a control decision?", back: "Statistical significance does not establish validity, causation, effect size, feasibility, or whether the association is due to bias or confounding.", source: "Question Marathon; Disease Detectives wiki" },
  { id: "dd-379", category: "Question Marathon", front: "What should you do when an outbreak hypothesis conflicts with laboratory evidence?", back: "Recheck case definitions, specimen timing, assay limitations, exposure histories, and alternative hypotheses; revise and re-evaluate rather than forcing agreement.", source: "13 outbreak-investigation steps; Disease Detectives Question Marathon" },
  { id: "dd-380", category: "Question Marathon", front: "What is the strongest answer structure for an applied Disease Detectives question?", back: "Name the measure or design, state the denominator and time frame, show the calculation or evidence, interpret direction and uncertainty, and identify a defensible action.", source: "Disease Detectives Question Marathon; CDC Principles of Epidemiology, Lesson 6" },
];
